39	 */
40	public class NumaResourceHandlerImpl implements ResourceHandler {
41	
42	  private static final Logger LOG = LoggerFactory
43	      .getLogger(NumaResourceHandlerImpl.class);
44	  private final NumaResourceAllocator numaResourceAllocator;
45	  private final String numaCtlCmd;
46	
47	  public NumaResourceHandlerImpl(Configuration conf, Context nmContext) {
48	    LOG.info("NUMA resources allocation is enabled, initializing NUMA resources"
49	        + " allocator.");
50	    numaResourceAllocator = new NumaResourceAllocator(nmContext);
51	    numaCtlCmd = conf.get(YarnConfiguration.NM_NUMA_AWARENESS_NUMACTL_CMD,
52	        YarnConfiguration.DEFAULT_NM_NUMA_AWARENESS_NUMACTL_CMD);
53	  }
54	
55	  @Override
56	  public List<PrivilegedOperation> bootstrap(Configuration configuration)
57	      throws ResourceHandlerException {
58	    try {
59	      numaResourceAllocator.init(configuration);
60	    } catch (YarnException e) {
61	      throw new ResourceHandlerException(e);
62	    }
63	    return null;
64	  }
65	
66	  @Override
67	  public List<PrivilegedOperation> preStart(Container container)
68	      throws ResourceHandlerException {
69	    List<PrivilegedOperation> ret = null;
70	    NumaResourceAllocation numaAllocation = numaResourceAllocator
71	        .allocateNumaNodes(container);
72	    if (numaAllocation != null) {
73	      ret = new ArrayList<>();
74	      ArrayList<String> args = new ArrayList<>();
75	      args.add(numaCtlCmd);
76	      args.add(
77	          "--interleave=" + String.join(",", numaAllocation.getMemNodes()));
78	      args.add(
79	          "--cpunodebind=" + String.join(",", numaAllocation.getCpuNodes()));
80	      ret.add(new PrivilegedOperation(OperationType.ADD_NUMA_PARAMS, args));
81	    }
82	    return ret;
83	  }
84	
85	  @Override
86	  public List<PrivilegedOperation> reacquireContainer(ContainerId containerId)
87	      throws ResourceHandlerException {
88	    try {
89	      numaResourceAllocator.recoverNumaResource(containerId);
90	    } catch (Throwable e) {
91	      throw new ResourceHandlerException(
92	          "Failed to recover numa resource for " + containerId, e);
93	    }
94	    return null;
95	  }
96	
97	  @Override
98	  public List<PrivilegedOperation> updateContainer(Container container)
99	      throws ResourceHandlerException {
100	    return null;
101	  }
102	
103	  @Override
104	  public List<PrivilegedOperation> postComplete(ContainerId containerId)
105	      throws ResourceHandlerException {
106	    numaResourceAllocator.releaseNumaResource(containerId);
107	    return null;
108	  }
109	
110	  @Override
111	  public List<PrivilegedOperation> teardown() throws ResourceHandlerException {
112	    return null;
113	  }
114	
115	  @Override
116	  public String toString() {
117	    return NumaResourceHandlerImpl.class.getName() + "{" +
118	        "numaResourceAllocator=" + numaResourceAllocator +
119	        ", numaCtlCmd='" + numaCtlCmd + '\'' +
120	        '}';
121	  }
122	}

